class DiagnosisProbe(view, device):
  def run_full_diagnosis(train_loader):
    panel = load_verified_training_panel(seed=42)
    save_modes_rng_and_buffers(view.model)
    try:
      set_eval(view.model)
      with no_grad():
        for category in ALL_FOUR_CATEGORIES:
          frequency_bins = build_bins_from_training_histories(category)
          for example in panel[category]:
            prefix, target, negative = example.fixed_inputs
            baseline = score(prefix, target, negative)
            record_unchanged_control(baseline, score(prefix, target, negative))
            for draw in range(5):
              positions = choose_older_positions(prefix, isolated_rng(draw))
              substituted, matching_info = substitute_in_place(
                prefix, positions, frequency_bins,
                exclude=example.complete_train_history | {target, negative})
              permuted = permute_older_occupied_slots(prefix, isolated_rng(draw))
              deleted = compact_after_deleting(prefix, positions)
              for condition in eligible_conditions(substituted, permuted, deleted):
                record_paired_scores_and_edit_strength(baseline, condition)
          average_draws_within_users_then_summarize(category)
        run_existing_twenty_user_full_catalog_recommendations()
        return {metrics: measurements_with_counts,
                metric_definitions: formulas_controls_and_limitations}
    finally:
      verify_buffers_and_restore_modes_rng(view.model)

def diagnosis_interpreter_prompt(raw_diagnosis):
  return render_prompt(raw_diagnosis.metrics, raw_diagnosis.metric_definitions,
    require_evidence_links=True,
    distinguish_sensitivity_from_predictive_quality=True,
    forbid_unobserved_preference_or_trait_claims=True)
